questionvariables.text:
/* Design: an at-least amount, two sizes, the cheapest combination (hiring stores). Source: adapted from SMP Book 5 (Metric), Chapter 8, Sections 2.1 to 2.2. The cheapest vertex is never whole; rounding x down there carries too little. Costs in Ksh. */
/* lincan(q): canonical form of a linear inequality in x and y: [strict?, [a, b, c]] meaning a*x + b*y + c (< or <=) 0 */
lincan(q) := block([r, d, s], r: op(q), d: expand(lhs(q) - rhs(q)),
    if r = ">" or r = ">=" then d: -d,
    s: is(r = "<" or r = ">"),
    [s, map(lambda([t], float(t)), [coeff(d, x), coeff(d, y), subst([x = 0, y = 0], d)])]);
lpar(u, v) := is(abs(u[1]*v[2] - u[2]*v[1]) + abs(u[1]*v[3] - u[3]*v[1]) + abs(u[2]*v[3] - u[3]*v[2]) < 1/10^9 * (abs(u[1]) + abs(u[2]) + abs(u[3])) * (abs(v[1]) + abs(v[2]) + abs(v[3])));
ldot(u, v) := u[1]*v[1] + u[2]*v[2] + u[3]*v[3];
/* lcls(L, T): "same" region; "dir" same boundary, other side, same strictness; "strict" same side, other strictness; "both"; "other" */
lcls(L, T) := block([l: lincan(L), t: lincan(T)],
    if not lpar(l[2], t[2]) then "other"
    elseif ldot(l[2], t[2]) > 0 then (if l[1] = t[1] then "same" else "strict")
    elseif l[1] = t[1] then "dir" else "both");
/* the validator: an inequality in x and y, linear */
validate_ineq(ex) := block([e: ev(ex, simp), d],
    if atom(e) or not member(op(e), ["<", "<=", ">", ">="]) then
        "Type an inequality using <, <=, > or >=, for example 2*x+3*y<=60. An equation with = is not an inequality."
    elseif listofvars(e) = [] or not every(lambda([v], member(v, [x, y])), listofvars(e)) then "Use only the letters x and y."
    else (d: ev(expand(lhs(e) - rhs(e)), simp),
          if not ev(polynomialp(d, [x, y]), simp) then
              "This inequality should be linear: only numbers times x and y, added or subtracted."
          elseif ev(hipow(d, x), simp) > 1 or ev(hipow(d, y), simp) > 1 or not freeof(x, ev(coeff(d, y), simp)) then
              "This inequality should be linear: no powers or products of x and y." else ""));
/* mkineq([a, b, rel, c]): the inequality a*x + b*y rel c */
mkineq(L) := if L[3] = "<=" then L[1]*x + L[2]*y <= L[4] elseif L[3] = "<" then L[1]*x + L[2]*y < L[4]
    elseif L[3] = ">=" then L[1]*x + L[2]*y >= L[4] else L[1]*x + L[2]*y > L[4];
Q42L: [["A cooperative in Narok must store at least \\(48\\) tonnes of wheat after the harvest. A small store holds \\(2\\) tonnes and costs Ksh \\(5000\\) to hire; a large store holds \\(7\\) tonnes and costs Ksh \\(9000\\). Only \\(5\\) large stores are free, and there are \\(15\\) watchmen, one for each store. Let \\(x\\) be the number of small stores and \\(y\\) the number of large stores hired.",2,7,48,5,15,5000,9000,[7,5],80000,77500,[6,5],[10,5],[7,6],"tonnes","(6.5, 5)","large stores",95000],
["A farmers' group in Nyandarua must keep at least \\(61\\) tonnes of potatoes in cold rooms. A small cold room holds \\(5\\) tonnes and costs Ksh \\(9000\\) to hire; a large cold room holds \\(11\\) tonnes and costs Ksh \\(10\\,000\\). Only \\(3\\) large cold rooms are free, and there are \\(14\\) attendants, one for each room. Let \\(x\\) be the number of small cold rooms and \\(y\\) the number of large cold rooms hired.",5,11,61,3,14,9000,10000,[6,3],84000,80400,[5,3],[11,3],[6,4],"tonnes","(5.6, 3)","large cold rooms",129000],
["A contractor in Machakos must keep at least \\(118\\) tonnes of cement under cover. A small shed holds \\(5\\) tonnes and costs Ksh \\(7000\\) to hire; a large shed holds \\(18\\) tonnes and costs Ksh \\(18\\,000\\). Only \\(5\\) large sheds are free, and there are \\(15\\) guards, one for each shed. Let \\(x\\) be the number of small sheds and \\(y\\) the number of large sheds hired.",5,18,118,5,15,7000,18000,[6,5],132000,129200,[5,5],[10,5],[6,6],"tonnes","(5.6, 5)","large sheds",160000],
["A traders' group at Wakulima market must keep at least \\(80\\) tonnes of tomatoes in cool stores. A small cool store holds \\(9\\) tonnes and costs Ksh \\(6000\\) to hire; a large cool store holds \\(13\\) tonnes and costs Ksh \\(7000\\). Only \\(3\\) large cool stores are free, and there are \\(10\\) attendants, one for each store. Let \\(x\\) be the number of small cool stores and \\(y\\) the number of large cool stores hired.",9,13,80,3,10,6000,7000,[6,2],50000,145000/3,[4,3],[7,3],[6,4],"tonnes","(\\frac{41}{9}, 3)","large cool stores",63000],
["A cooperative in Mwea must store at least \\(157\\) tonnes of rice. A small warehouse holds \\(8\\) tonnes and costs Ksh \\(9000\\) to hire; a large warehouse holds \\(19\\) tonnes and costs Ksh \\(13\\,000\\). Only \\(6\\) large warehouses are free, and there are \\(15\\) watchmen, one for each warehouse. Let \\(x\\) be the number of small warehouses and \\(y\\) the number of large warehouses hired.",8,19,157,6,15,9000,13000,[6,6],132000,126375,[5,6],[9,6],[6,7],"tonnes","(5.375, 6)","large warehouses",159000],
["A dairy farmers' group in Nyandarua must store at least \\(60\\) tonnes of hay for the dry season. A small barn holds \\(3\\) tonnes and costs Ksh \\(5000\\) to hire; a large barn holds \\(8\\) tonnes and costs Ksh \\(8000\\). Only \\(5\\) large barns are free, and there are \\(15\\) workers, one for each barn. Let \\(x\\) be the number of small barns and \\(y\\) the number of large barns hired.",3,8,60,5,15,5000,8000,[7,5],75000,220000/3,[6,5],[10,5],[7,6],"tonnes","(\\frac{20}{3}, 5)","large barns",90000],
["A county agriculture office in Kitale must store at least \\(77\\) tonnes of fertiliser. A small store holds \\(6\\) tonnes and costs Ksh \\(8000\\) to hire; a large store holds \\(17\\) tonnes and costs Ksh \\(9000\\). Only \\(3\\) large stores are free, and there are \\(15\\) storekeepers, one for each store. Let \\(x\\) be the number of small stores and \\(y\\) the number of large stores hired.",6,17,77,3,15,8000,9000,[5,3],67000,185000/3,[4,3],[12,3],[5,4],"tonnes","(\\frac{13}{3}, 3)","large stores",123000],
["A farmers' group in Bahati must keep at least \\(125\\) tonnes of cabbages in cold rooms before market day. A small cold room holds \\(7\\) tonnes and costs Ksh \\(5000\\) to hire; a large cold room holds \\(15\\) tonnes and costs Ksh \\(9000\\). Only \\(5\\) large cold rooms are free, and there are \\(16\\) attendants, one for each room. Let \\(x\\) be the number of small cold rooms and \\(y\\) the number of large cold rooms hired.",7,15,125,5,16,5000,9000,[8,5],85000,565000/7,[7,5],[11,5],[8,6],"tonnes","(\\frac{50}{7}, 5)","large cold rooms",100000],
["A school board in Kitui must keep at least \\(71\\) tonnes of cement dry on a building site. A small container holds \\(3\\) tonnes and costs Ksh \\(9000\\) to hire; a large container holds \\(17\\) tonnes and costs Ksh \\(11\\,000\\). Only \\(3\\) large containers are free, and there are \\(15\\) guards, one for each container. Let \\(x\\) be the number of small containers and \\(y\\) the number of large containers hired.",3,17,71,3,15,9000,11000,[7,3],96000,93000,[6,3],[12,3],[7,4],"tonnes","(\\frac{20}{3}, 3)","large containers",141000],
["A county water office near Garissa must store at least \\(35\\) drums of water for a village. A small tank holds \\(2\\) drums and costs Ksh \\(7000\\) to hire; a large tank holds \\(13\\) drums and costs Ksh \\(11\\,000\\). Only \\(2\\) large tanks are free, and there is space for \\(15\\) tanks. Let \\(x\\) be the number of small tanks and \\(y\\) the number of large tanks hired.",2,13,35,2,15,7000,11000,[5,2],57000,53500,[4,2],[13,2],[5,3],"drums","(4.5, 2)","large tanks",113000]];
ix: 1+rand(10);
E: Q42L[ix];
ca: E[2]; cb: E[3]; RR: E[4]; YY: E[5]; NN: E[6]; cx: E[7]; cy: E[8]; bst: E[9]; t: E[10]; tv: E[11]; dn: E[12]; wst: E[13]; lb: E[14]; un: E[15]; vd: E[16]; lg: E[17]; tw: E[18];
ta1: ca*x+cb*y>=RR; sw1: cb*x+ca*y>=RR; dr1: ca*x+cb*y<=RR;
Cof(u, w) := cx*u + cy*w;
validate_int(ex) := if integerp(ev(ex, simp)) then "" else "Type whole numbers.";
g3(v) := block([q,r], if v < 1000 then string(v) else (q: floor(v/1000), r: v - 1000*q, sconcat(g3(q), "\\,", if r < 10 then "00" elseif r < 100 then "0" else "", string(r))));
thou(v) := if abs(v) < 10000 then string(v) else g3(v);
